func (c *Core) cdlharamicrossOpenAndFillInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32, outBegIdx, outNBElement *int32, outInteger []int32) (*CDLHARAMICROSSStream, error) {
	sp := &CDLHARAMICROSSStream{core: c}
	if retCode := c.cdlharamicrossOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, outBegIdx, outNBElement, outInteger, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) cdlharamicrossOpenInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32) (*CDLHARAMICROSSStream, error) {
	sp := &CDLHARAMICROSSStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outInteger [1]int32
	if retCode := c.cdlharamicrossOpenSinkFrame(sp, inOpen, inHigh, inLow, inClose, startIdx, &outBegIdx, &outNBElement, sink_outInteger[:]); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// CDLHARAMICROSSOpen opens a live [CDLHARAMICROSSStream] on a warm-up history,
// oldest bar first, and returns it with its value at the last history bar, the
// value [Core.CDLHARAMICROSS] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length.
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDLHARAMICROSSLookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for histories of different lengths.
func (c *Core) CDLHARAMICROSSOpen(inOpen, inHigh, inLow, inClose []float64) (*CDLHARAMICROSSStream, int32, error) {
	sp, err := c.cdlharamicrossOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLHARAMICROSSOpenAndFill opens a stream as [Core.CDLHARAMICROSSOpen] does
// and also writes the outputs over the whole history, as [Core.CDLHARAMICROSS]
// writes them for bars 0 through len(inOpen)-1, returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLHARAMICROSSLookback] values
// and share no memory with an input or another output.
//
// The errors are those of [Core.CDLHARAMICROSSOpen], and [BadParam] for an
// output that is empty, too short or sharing memory.
func (c *Core) CDLHARAMICROSSOpenAndFill(inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (*CDLHARAMICROSSStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdlharamicrossLookback())
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdlharamicrossOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
